    public async Task<CrmPage<ActivityDto>> ListActivitiesAsync(TenantId tenant, Guid entity, Guid? actor, string? state, int page, int size, string? scope, CancellationToken ct) { page = Math.Max(1, page); size = Math.Clamp(size, 1, 200); await using var s = await OpenAsync(tenant, ct); var st = string.IsNullOrWhiteSpace(state) ? null : state.Trim(); var mine = !string.Equals(scope, "all", StringComparison.OrdinalIgnoreCase); var count = new NpgsqlCommand("select count(*) from business_crm.crm_activity where tenant_id=$1 and legal_entity_id=$2 and ($3::text is null or state=$3) and ($4::boolean=false or owner_id=$5 or exists(select 1 from business_crm.crm_sales_team_member tm where tm.tenant_id=business_crm.crm_activity.tenant_id and tm.legal_entity_id=business_crm.crm_activity.legal_entity_id and tm.user_id=$5 and tm.team_id in (select team_id from business_crm.opportunity where tenant_id=business_crm.crm_activity.tenant_id and id=business_crm.crm_activity.opportunity_id union select team_id from business_crm.lead where tenant_id=business_crm.crm_activity.tenant_id and id=business_crm.crm_activity.lead_id) and tm.active_from <= current_date and (tm.active_to is null or tm.active_to >= current_date)))", s.Connection, s.Transaction); Add(count, tenant.Value, entity, Db(st), mine, Db(actor)); var total = Convert.ToInt32(await count.ExecuteScalarAsync(ct)); await using var c = new NpgsqlCommand("select id,legal_entity_id,lead_id,opportunity_id,party_id,type,subject,state,due_at,completed_at,outcome,notes,owner_id,version from business_crm.crm_activity where tenant_id=$1 and legal_entity_id=$2 and ($3::text is null or state=$3) and ($4::boolean=false or owner_id=$5 or exists(select 1 from business_crm.crm_sales_team_member tm where tm.tenant_id=business_crm.crm_activity.tenant_id and tm.legal_entity_id=business_crm.crm_activity.legal_entity_id and tm.user_id=$5 and tm.team_id in (select team_id from business_crm.opportunity where tenant_id=business_crm.crm_activity.tenant_id and id=business_crm.crm_activity.opportunity_id union select team_id from business_crm.lead where tenant_id=business_crm.crm_activity.tenant_id and id=business_crm.crm_activity.lead_id) and tm.active_from <= current_date and (tm.active_to is null or tm.active_to >= current_date))) order by due_at offset $6 limit $7", s.Connection, s.Transaction); Add(c, tenant.Value, entity, Db(st), mine, Db(actor), (page - 1) * size, size); var list = new List<ActivityDto>(); await using var r = await c.ExecuteReaderAsync(ct); while (await r.ReadAsync(ct)) list.Add(ReadActivity(r)); await r.CloseAsync(); await CommitAsync(s); return new(list, total, page, size); }

    public async Task<CrmPage<ActivityDto>> ListSellerActivitiesAsync(TenantId tenant, Guid entity, Guid? actor, string mode, bool allAuthorized, int page, int size, CancellationToken ct)
    {
        page = Math.Max(1, page); size = Math.Clamp(size, 1, 200); var mine = !allAuthorized;
        var predicate = mode switch
        {
            "home" => "a.state='Scheduled' and a.due_at < current_date + interval '1 day'",
            "attention" => "a.state='Scheduled' and (a.due_at < now() or o.health_status in ('AtRisk','Stale') or (o.status='Open' and o.expected_close_date < current_date))",
            _ => "a.state='Scheduled'"
        };
        await using var s = await OpenAsync(tenant, ct);
        var filter = "a.tenant_id=$1 and a.legal_entity_id=$2 and (not $3::boolean or a.owner_id=$4 or exists(select 1 from business_crm.crm_sales_team_member tm where tm.tenant_id=a.tenant_id and tm.legal_entity_id=a.legal_entity_id and tm.team_id=(select team_id from business_crm.opportunity where tenant_id=a.tenant_id and id=a.opportunity_id) and tm.user_id=$4 and tm.active_from <= current_date and (tm.active_to is null or tm.active_to >= current_date))) and " + predicate;
        await using var count = new NpgsqlCommand("select count(*) from business_crm.crm_activity a left join business_crm.opportunity o on o.tenant_id=a.tenant_id and o.legal_entity_id=a.legal_entity_id and o.id=a.opportunity_id where " + filter, s.Connection, s.Transaction); Add(count, tenant.Value, entity, mine, Db(actor)); var total = Convert.ToInt32(await count.ExecuteScalarAsync(ct));
        await using var c = new NpgsqlCommand("select a.id,a.legal_entity_id,a.lead_id,a.opportunity_id,a.party_id,a.type,a.subject,a.state,a.due_at,a.completed_at,a.outcome,a.notes,a.owner_id,a.version from business_crm.crm_activity a left join business_crm.opportunity o on o.tenant_id=a.tenant_id and o.legal_entity_id=a.legal_entity_id and o.id=a.opportunity_id where " + filter + " order by case when a.due_at < now() then 0 else 1 end,a.due_at,a.created_at offset $5 limit $6", s.Connection, s.Transaction); Add(c, tenant.Value, entity, mine, Db(actor), (page - 1) * size, size); var list = new List<ActivityDto>(); await using var r = await c.ExecuteReaderAsync(ct); while (await r.ReadAsync(ct)) list.Add(ReadActivity(r)); await r.CloseAsync(); await CommitAsync(s); return new(list, total, page, size);
    }
