    public async Task<IReadOnlyList<PipelineDto>> ListPipelinesAsync(TenantId tenant, Guid entity, CancellationToken ct) { await using var s = await OpenAsync(tenant, ct); await using var c = new NpgsqlCommand("select id,legal_entity_id,code,name,status,is_default from business_crm.crm_pipeline where tenant_id=$1 and legal_entity_id=$2 and status='Active' order by is_default desc,code", s.Connection, s.Transaction); Add(c, tenant.Value, entity); var rows = new List<(Guid Id, Guid Entity, string Code, string Name, string Status, bool IsDefault)>(); await using (var r = await c.ExecuteReaderAsync(ct)) { while (await r.ReadAsync(ct)) rows.Add((r.GetGuid(0), r.GetGuid(1), r.GetString(2), r.GetString(3), r.GetString(4), r.GetBoolean(5))); } var list = new List<PipelineDto>(rows.Count); foreach (var row in rows) list.Add(new(row.Id, row.Entity, row.Code, row.Name, row.Status, row.IsDefault, await ReadStagesAsync(s.Connection, s.Transaction, tenant, row.Id, ct))); await CommitAsync(s); return list; }
