    public async Task<ForecastDto> ForecastAsync(TenantId tenant, Guid entity, DateOnly? from, DateOnly? to, string currency, CancellationToken ct) { await using var s = await OpenAsync(tenant, ct); var start = from ?? DateOnly.MinValue; var end = to ?? DateOnly.MaxValue; await using var c = new NpgsqlCommand("select coalesce(sum(estimated_amount),0),coalesce(sum(estimated_amount*coalesce(st.probability,0)),0),coalesce(sum(o.estimated_amount) filter(where o.forecast_category='BestCase'),0),coalesce(sum(o.estimated_amount) filter(where o.forecast_category='Commit'),0),coalesce(sum(o.estimated_amount) filter(where o.status='Won'),0),count(*) filter(where o.status='Open'),count(*) filter(where o.status='Open' and o.health_status in ('AtRisk','Stale')),count(*) filter(where o.status='Open' and o.expected_close_date < current_date) from business_crm.opportunity o join business_crm.crm_pipeline_stage st on st.tenant_id=o.tenant_id and st.id=o.stage_id where o.tenant_id=$1 and o.legal_entity_id=$2 and rtrim(o.currency_code)=$3 and (o.expected_close_date is null or o.expected_close_date between $4 and $5)", s.Connection, s.Transaction); Add(c, tenant.Value, entity, currency.Trim().ToUpperInvariant(), start, end); await using var r = await c.ExecuteReaderAsync(ct); await r.ReadAsync(ct); var result = new ForecastDto(r.GetDecimal(0), r.GetDecimal(1), r.GetDecimal(2), r.GetDecimal(3), r.GetDecimal(4), r.GetInt64(5) > int.MaxValue ? int.MaxValue : (int)r.GetInt64(5), r.GetInt64(6) > int.MaxValue ? int.MaxValue : (int)r.GetInt64(6), r.GetInt64(7) > int.MaxValue ? int.MaxValue : (int)r.GetInt64(7), currency.Trim().ToUpperInvariant()); await r.CloseAsync(); await CommitAsync(s); return result; }
    public async Task<Customer360Dto?> Customer360Async(TenantId tenant, Guid entity, Guid partyId, CancellationToken ct) { await using var s = await OpenAsync(tenant, ct); await using var c = new NpgsqlCommand("select p.party_id,coalesce(p.relationship_health,'Unknown'),p.do_not_contact,count(o.id) filter(where o.status='Open'),coalesce(sum(o.estimated_amount) filter(where o.status='Open'),0),max(a.completed_at),min(a.due_at) filter(where a.state='Scheduled') from business_crm.crm_party_profile p left join business_crm.opportunity o on o.tenant_id=p.tenant_id and o.legal_entity_id=p.legal_entity_id and o.party_id=p.party_id left join business_crm.crm_activity a on a.tenant_id=p.tenant_id and a.legal_entity_id=p.legal_entity_id and a.party_id=p.party_id where p.tenant_id=$1 and p.legal_entity_id=$2 and p.party_id=$3 group by p.party_id,p.relationship_health,p.do_not_contact", s.Connection, s.Transaction); Add(c, tenant.Value, entity, partyId); await using var r = await c.ExecuteReaderAsync(ct); if (!await r.ReadAsync(ct)) { await r.CloseAsync(); await CommitAsync(s); return null; } var result = new Customer360Dto(r.GetGuid(0), entity, "", r.GetInt64(3) > int.MaxValue ? int.MaxValue : (int)r.GetInt64(3), r.GetDecimal(4), r.IsDBNull(5) ? null : r.GetFieldValue<DateTimeOffset>(5), r.IsDBNull(6) ? null : r.GetFieldValue<DateTimeOffset>(6), r.GetString(1), r.GetBoolean(2)); await r.CloseAsync(); await CommitAsync(s); return result; }

    public async Task<LeadDto> MergeLeadsAsync(TenantId tenant, Guid actor, Guid entity, MergeLeadsRequest request, CancellationToken ct)
    {
        if (request.SourceLeadId == request.TargetLeadId) throw new CrmException("crm.merge_same_lead");
        await using var s = await OpenAsync(tenant, ct);
        await using var c = new NpgsqlCommand("select id,status,version from business_crm.lead where tenant_id=$1 and legal_entity_id=$2 and id in ($3,$4) order by id for update", s.Connection, s.Transaction);
        Add(c, tenant.Value, entity, request.SourceLeadId, request.TargetLeadId); var versions = new Dictionary<Guid, (string Status, long Version)>(); await using var r = await c.ExecuteReaderAsync(ct); while (await r.ReadAsync(ct)) versions[r.GetGuid(0)] = (r.GetString(1), r.GetInt64(2)); await r.CloseAsync();
        if (!versions.TryGetValue(request.SourceLeadId, out var source) || !versions.TryGetValue(request.TargetLeadId, out var target)) throw new CrmException("crm.lead_not_found");
        if (source.Version != request.SourceVersion || target.Version != request.TargetVersion) throw new CrmException("crm.lead_stale");
        if (source.Status is "Converted" or "Archived") throw new CrmException("crm.lead_not_mergeable");
        await using var update = new NpgsqlCommand("update business_crm.lead set status='Archived',disqualified_reason='Merged into target lead',version=version+1,updated_at=now() where tenant_id=$1 and legal_entity_id=$2 and id=$3", s.Connection, s.Transaction); Add(update, tenant.Value, entity, request.SourceLeadId); await update.ExecuteNonQueryAsync(ct); await CommitAsync(s); return (await GetLeadAsync(tenant, entity, request.TargetLeadId, ct))!;
    }

