    public async Task CompleteLeadConversionAsync(TenantId tenant, Guid actor, Guid entity, Guid leadId, Guid partyId, Guid opportunityId, string key, long version, CancellationToken ct)
    { await using var s = await OpenAsync(tenant, ct); await using var current = new NpgsqlCommand("select status,version from business_crm.lead where tenant_id=$1 and legal_entity_id=$2 and id=$3 for update", s.Connection, s.Transaction); Add(current, tenant.Value, entity, leadId); await using var reader = await current.ExecuteReaderAsync(ct); if (!await reader.ReadAsync(ct)) throw new CrmException("crm.lead_not_found"); var state = reader.GetString(0); var currentVersion = reader.GetInt64(1); await reader.CloseAsync(); if (state == "Converted") { await CommitAsync(s); return; } if (currentVersion != version) throw new CrmException("crm.lead_stale"); if (state != "Qualified") throw new CrmException("crm.lead_not_qualified"); await using var insert = new NpgsqlCommand("insert into business_crm.lead_conversion(tenant_id,id,legal_entity_id,lead_id,party_id,opportunity_id,idempotency_key,payload_hash,converted_by,converted_at) values($1,$2,$3,$4,$5,$6,$7,$8,$9,now()) on conflict(tenant_id,lead_id) do nothing returning opportunity_id", s.Connection, s.Transaction); Add(insert, tenant.Value, Guid.CreateVersion7(), entity, leadId, partyId, opportunityId, key, Hash(key + opportunityId.ToString("D")), actor); if (await insert.ExecuteScalarAsync(ct) is null) { await CommitAsync(s); return; } await using var update = new NpgsqlCommand("update business_crm.lead set status='Converted',party_id=$4,opportunity_id=$5,converted_at=now(),version=version+1,updated_at=now() where tenant_id=$1 and legal_entity_id=$2 and id=$3", s.Connection, s.Transaction); Add(update, tenant.Value, entity, leadId, partyId, opportunityId); await update.ExecuteNonQueryAsync(ct); await CommitAsync(s); }

