    private static LeadDto ReadLead(NpgsqlDataReader r) { var ids = Array.Empty<Guid>(); return new(r.GetGuid(0), r.GetGuid(1), r.GetString(2), Text(r, 3), Text(r, 4), Text(r, 5), r.GetString(6), r.GetString(7), GuidValue(r, 8), GuidValue(r, 9), r.GetString(10), r.GetInt32(11), GuidValue(r, 12), GuidValue(r, 13), r.IsDBNull(14) ? null : r.GetFieldValue<DateTimeOffset>(14), r.GetInt64(15), r.GetFieldValue<DateTimeOffset>(16), ids); }
