    private static ActivityDto ReadActivity(NpgsqlDataReader r) => new(r.GetGuid(0), r.GetGuid(1), GuidValue(r, 2), GuidValue(r, 3), GuidValue(r, 4), r.GetString(5), r.GetString(6), r.GetString(7), r.GetFieldValue<DateTimeOffset>(8), r.IsDBNull(9) ? null : r.GetFieldValue<DateTimeOffset>(9), Text(r, 10), Text(r, 11), GuidValue(r, 12), r.GetInt64(13));
