    private static async Task<IReadOnlyList<Guid>> DuplicateIdsAsync(NpgsqlConnection c, NpgsqlTransaction t, TenantId tenant, Guid entity, string? email, string? phone, Guid? except, CancellationToken ct) { await using var cmd = new NpgsqlCommand("select id from business_crm.lead where tenant_id=$1 and legal_entity_id=$2 and id<>coalesce($5::uuid,'00000000-0000-0000-0000-000000000000'::uuid) and (($3::text is not null and normalized_email=$3) or ($4::text is not null and normalized_phone=$4)) and status<>'Archived' order by created_at desc limit 20", c, t); Add(cmd, tenant.Value, entity, Db(email), Db(phone), Db(except)); var list = new List<Guid>(); await using var r = await cmd.ExecuteReaderAsync(ct); while (await r.ReadAsync(ct)) list.Add(r.GetGuid(0)); return list; }
    private static string? NormalizeEmail(string? value) => string.IsNullOrWhiteSpace(value) ? null : value.Trim().ToLowerInvariant();
    private static string? NormalizePhone(string? value) => string.IsNullOrWhiteSpace(value) ? null : new string(value.Where(char.IsDigit).ToArray());
    private static string Hash(string value) => Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(value))).ToLowerInvariant();
    private static string? Text(NpgsqlDataReader r, int i) => r.IsDBNull(i) ? null : r.GetString(i);
    private static Guid? GuidValue(NpgsqlDataReader r, int i) => r.IsDBNull(i) ? null : r.GetGuid(i);
    private static object Db(object? value) => value ?? DBNull.Value;
    private static void Add(NpgsqlCommand c, params object?[] values) { foreach (var value in values) c.Parameters.AddWithValue(value ?? DBNull.Value); }
    private static async Task ExecuteAsync(TransactionScope s, string sql, CancellationToken ct, params object?[] values) { await using var c = new NpgsqlCommand(sql, s.Connection, s.Transaction); Add(c, values); await c.ExecuteNonQueryAsync(ct); }
    private static async Task CommitAsync(TransactionScope s) => await s.Transaction.CommitAsync();
    private async Task<TransactionScope> OpenAsync(TenantId tenant, CancellationToken ct) { var c = await dataSource.OpenConnectionAsync(ct); var t = await c.BeginTransactionAsync(ct); await using var set = new NpgsqlCommand("select set_config('app.tenant_id',$1,true)", c, t); Add(set, tenant.Value.ToString("D")); await set.ExecuteNonQueryAsync(ct); return new(c, t); }
    private sealed class TransactionScope(NpgsqlConnection connection, NpgsqlTransaction transaction) : IAsyncDisposable { public NpgsqlConnection Connection { get; } = connection; public NpgsqlTransaction Transaction { get; } = transaction; public ValueTask DisposeAsync() => Connection.DisposeAsync(); }

    public async Task<OpportunityDto> UpdateOpportunityAsync(TenantId tenant, Guid entity, Guid id, UpdateOpportunityRequest request, CancellationToken ct)
    { if (request.EstimatedAmount < 0) throw new CrmException("crm.opportunity_value_invalid"); await using var s = await OpenAsync(tenant, ct); await using var c = new NpgsqlCommand("update business_crm.opportunity set name=$4,estimated_amount=$5,expected_close_date=$6,forecast_category=$7,version=version+1,updated_at=now() where tenant_id=$1 and legal_entity_id=$2 and id=$3 and version=$8 returning id", s.Connection, s.Transaction); Add(c, tenant.Value, entity, id, request.Name.Trim(), request.EstimatedAmount, Db(request.ExpectedCloseDate), request.ForecastCategory.Trim(), request.Version); if (await c.ExecuteScalarAsync(ct) is null) throw new CrmException("crm.opportunity_stale"); await CommitAsync(s); return (await GetOpportunityAsync(tenant, entity, id, ct))!; }

    public async Task<OpportunityDto> AssignOpportunityAsync(TenantId tenant, Guid actor, Guid entity, Guid id, AssignOpportunityRequest request, CancellationToken ct) { await using var s = await OpenAsync(tenant, ct); await using var c = new NpgsqlCommand("update business_crm.opportunity set owner_id=$4,team_id=$5,version=version+1,updated_at=now() where tenant_id=$1 and legal_entity_id=$2 and id=$3 and version=$6 returning id", s.Connection, s.Transaction); Add(c, tenant.Value, entity, id, Db(request.OwnerId), Db(request.TeamId), request.Version); if (await c.ExecuteScalarAsync(ct) is null) throw new CrmException("crm.opportunity_stale"); await CommitAsync(s); return (await GetOpportunityAsync(tenant, entity, id, ct))!; }
    public async Task<OpportunityDto> SetForecastCategoryAsync(TenantId tenant, Guid entity, Guid id, ForecastCategoryRequest request, CancellationToken ct) { if (request.Category is not ("Pipeline" or "BestCase" or "Commit" or "Won" or "Omitted")) throw new CrmException("crm.forecast_category_invalid"); await using var s = await OpenAsync(tenant, ct); await using var c = new NpgsqlCommand("update business_crm.opportunity set forecast_category=$4,version=version+1,updated_at=now() where tenant_id=$1 and legal_entity_id=$2 and id=$3 and version=$5 returning id", s.Connection, s.Transaction); Add(c, tenant.Value, entity, id, request.Category, request.Version); if (await c.ExecuteScalarAsync(ct) is null) throw new CrmException("crm.opportunity_stale"); await CommitAsync(s); return (await GetOpportunityAsync(tenant, entity, id, ct))!; }
    public async Task<IReadOnlyList<TeamDto>> ListTeamsAsync(TenantId tenant, Guid entity, CancellationToken ct) { await using var s = await OpenAsync(tenant, ct); await using var c = new NpgsqlCommand("select id,legal_entity_id,code,name,manager_id,status from business_crm.crm_sales_team where tenant_id=$1 and legal_entity_id=$2 and status='Active' order by code", s.Connection, s.Transaction); Add(c, tenant.Value, entity); var list = new List<TeamDto>(); await using var r = await c.ExecuteReaderAsync(ct); while (await r.ReadAsync(ct)) list.Add(new(r.GetGuid(0), r.GetGuid(1), r.GetString(2), r.GetString(3), GuidValue(r, 4), r.GetString(5))); await r.CloseAsync(); await CommitAsync(s); return list; }
    public async Task<TeamDto> CreateTeamAsync(TenantId tenant, CreateTeamRequest request, CancellationToken ct) { await using var s = await OpenAsync(tenant, ct); var id = Guid.CreateVersion7(); await using var c = new NpgsqlCommand("insert into business_crm.crm_sales_team(tenant_id,id,legal_entity_id,code,name,manager_id) values($1,$2,$3,$4,$5,$6) returning id", s.Connection, s.Transaction); Add(c, tenant.Value, id, request.LegalEntityId, request.Code.Trim().ToUpperInvariant(), request.Name.Trim(), Db(request.ManagerId)); await c.ExecuteScalarAsync(ct); await CommitAsync(s); return (await ListTeamsAsync(tenant, request.LegalEntityId, ct)).Single(x => x.Id == id); }

    public async Task<IReadOnlyList<TeamMemberDto>> ListTeamMembersAsync(TenantId tenant, Guid entity, Guid teamId, CancellationToken ct)
    {
        await using var s = await OpenAsync(tenant, ct);
        await using var c = new NpgsqlCommand("select team_id,user_id,role,active_from,active_to from business_crm.crm_sales_team_member where tenant_id=$1 and legal_entity_id=$2 and team_id=$3 and (active_to is null or active_to >= current_date) order by active_from,user_id", s.Connection, s.Transaction);
        Add(c, tenant.Value, entity, teamId);
        var list = new List<TeamMemberDto>();
        await using var r = await c.ExecuteReaderAsync(ct);
        while (await r.ReadAsync(ct)) list.Add(new(r.GetGuid(0), r.GetGuid(1), r.GetString(2), r.GetFieldValue<DateOnly>(3), r.IsDBNull(4) ? null : r.GetFieldValue<DateOnly>(4)));
        await r.CloseAsync(); await CommitAsync(s); return list;
    }

    public async Task<TeamMemberDto> AddTeamMemberAsync(TenantId tenant, Guid entity, Guid teamId, AddTeamMemberRequest request, CancellationToken ct)
    {
        await using var s = await OpenAsync(tenant, ct);
        var from = request.ActiveFrom ?? DateOnly.FromDateTime(DateTime.UtcNow.Date);
        await using var c = new NpgsqlCommand("insert into business_crm.crm_sales_team_member(tenant_id,id,legal_entity_id,team_id,user_id,role,active_from) select $1,$2,legal_entity_id,$3,$4,$5,$6 from business_crm.crm_sales_team where tenant_id=$1 and legal_entity_id=$7 and id=$3 returning team_id,user_id,role,active_from,active_to", s.Connection, s.Transaction);
        Add(c, tenant.Value, Guid.CreateVersion7(), teamId, request.UserId, request.Role.Trim(), from, entity);
        await using var r = await c.ExecuteReaderAsync(ct);
        if (!await r.ReadAsync(ct)) throw new CrmException("crm.team_not_found");
        var member = new TeamMemberDto(r.GetGuid(0), r.GetGuid(1), r.GetString(2), r.GetFieldValue<DateOnly>(3), r.IsDBNull(4) ? null : r.GetFieldValue<DateOnly>(4));
        await r.CloseAsync(); await CommitAsync(s); return member;
    }

    public async Task EndTeamMemberAsync(TenantId tenant, Guid entity, Guid teamId, Guid userId, CancellationToken ct)
    {
        await using var s = await OpenAsync(tenant, ct);
        await using var c = new NpgsqlCommand("update business_crm.crm_sales_team_member set active_to=current_date where tenant_id=$1 and legal_entity_id=$2 and team_id=$3 and user_id=$4 and active_to is null", s.Connection, s.Transaction);
        Add(c, tenant.Value, entity, teamId, userId); await c.ExecuteNonQueryAsync(ct); await CommitAsync(s);
    }
}
